def card(a,lang):
 d=a[lang]; ru=lang=='ru'; source='Архитектура · статья' if ru else 'Architecture · article'; versions='Доступные языковые версии' if ru else 'Available language versions'; meta=f"{a['read']} мин" if ru else f"{a['read']} min"; s=a['slug'];
 if ru: links=f'<a href="../articles/{s}.html" aria-current="true">RU</a><a href="../../en/articles/{s}.html">EN</a>'
 else: links=f'<a href="../../ru/articles/{s}.html">RU</a><a href="../articles/{s}.html" aria-current="true">EN</a>'
 return f'<article class="publication-item"><div class="publication-meta"><span>{meta}</span></div><div class="publication-copy"><p class="publication-source">{source}</p><h3><a href="../articles/{s}.html">{esc(d["title"])}</a></h3><p>{esc(d["desc"])}</p></div><nav class="publication-versions" aria-label="{versions}">{links}</nav></article>'

def insert_card(text,cat,html_card,slug):
 if slug+'.html' in text: return text
 m=re.search(rf'(<section[^>]+id=[\'\"]{re.escape(cat)}[\'\"][\s\S]*?<div[^>]+class=[\'\"]publication-list[\'\"]>)([\s\S]*?)(</div></section>)',text)
 if not m: raise RuntimeError('section '+cat+' not found')
 return text[:m.start()]+m.group(1)+m.group(2)+html_card+m.group(3)+text[m.end():]

